ALTER TABLE "model_provider_attempts" ADD COLUMN "continuation_authorized_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "model_provider_attempts" ADD COLUMN "continuation_expires_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "model_provider_attempts" ADD COLUMN "continuation_authorization_hash" text;--> statement-breakpoint
ALTER TABLE "model_provider_attempts" ADD CONSTRAINT "model_provider_continuation_authorization" CHECK (("model_provider_attempts"."continuation_authorized_at" IS NULL AND "model_provider_attempts"."continuation_expires_at" IS NULL AND "model_provider_attempts"."continuation_authorization_hash" IS NULL) OR ("model_provider_attempts"."status" = 'unknown' AND "model_provider_attempts"."continuation_authorized_at" IS NOT NULL AND "model_provider_attempts"."continuation_expires_at" IS NOT NULL AND "model_provider_attempts"."continuation_authorization_hash" IS NOT NULL AND "model_provider_attempts"."continuation_expires_at" > "model_provider_attempts"."continuation_authorized_at" AND "model_provider_attempts"."continuation_expires_at" <= "model_provider_attempts"."continuation_authorized_at" + interval '1 hour' AND "model_provider_attempts"."continuation_authorization_hash" ~ '^[a-f0-9]{64}$'));